/**
 * Checks this codec against `protocol/test-vectors.json`, generated by `tools/host` from its
 * reference codec. Read-only: the file belongs to the tools side.
 */

import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import {
  decodeS32,
  decodeU14,
  decodeU28,
  decodeU32,
  encodeS32,
  encodeU14,
  encodeU28,
  encodeU32,
  pack,
  unpack,
} from './encoding.ts';
import { parseComponent } from './feedback.ts';
import { checksum, decodeFrame, encodeFrame, FrameProblem } from './frame.ts';
import { planChunks, readHeader, validateImage } from './image.ts';
import { keyRects, parseLayout } from './layout.ts';
import {
  encoderDelta,
  getParamPayload,
  getParamsPayload,
  getSchemaPayload,
  parseDeviceMessage,
  parseHello,
  parseParamRun,
  parseParamRunEcho,
  parseParamValue,
  parseSchemaWindow,
  setParamPayload,
  setParamsPayload,
} from './messages.ts';
import { monitorPayload, parseMonitorReply, parseRaw } from './monitor.ts';
import { type ParamSpec, parseSchema, SchemaError } from './schema.ts';
import {
  Capability,
  Command,
  LayoutShape,
  MonitorKind,
  NOTIFICATION_FIRST,
  NOTIFICATION_LAST,
  ParamFlag,
  RAW_NO_READING,
  RawKind,
  REPLY_FLAG,
  Status,
  Unsolicited,
} from './wire.ts';

const VECTORS_URL = new URL('../../../../protocol/test-vectors.json', import.meta.url);

interface IntVector {
  value: number;
  bytes: string;
}
/** A param as the vectors write it: absent strings and lists are empty. */
interface VectorParam {
  id: number;
  type: number;
  group: number;
  count: number;
  flags: number;
  min: number;
  max: number;
  defaults: number[];
  name: string;
  label: string;
  unit: string;
  index_labels: string[];
  options?: string[];
}
/** The decoded fields of a config frame. */
interface ConfigFields {
  status?: number;
  offset?: number;
  max?: number;
  total?: number;
  data?: string;
  id?: number;
  index?: number;
  value?: number;
  n?: number;
  values?: number[];
  type?: number;
  delta?: number;
  t_ms?: number;
}
interface ConfigVectors {
  s32: IntVector[];
  schema: { raw: string; size: number; parsed: { version: number; groups: string[]; params: VectorParam[] } };
  bad_schemas: { desc: string; raw: string; error: string }[];
  frames: { desc: string; cmd: number; seq: number; payload: string; frame: string; fields?: ConfigFields }[];
}
/** The decoded fields of a feedback frame that the checks below compare (the rest are checked by tools/host). */
interface FeedbackFields {
  status?: number;
  kind?: number;
  takeover?: number | null;
  mode?: number | null;
  owner?: number | null;
  board_id?: number;
  fw_version?: number;
  caps?: number;
  uid?: string;
  node?: string | null;
}
/** One frame as the vectors write it. */
interface VectorFrame {
  desc: string;
  cmd: number;
  seq: number;
  payload: string;
  frame: string;
  fields?: FeedbackFields;
}
/** A layout item as the vectors write it (§4.7). */
interface VectorLayoutItem {
  kind: number;
  index: number;
  shape: number;
  x: number;
  y: number;
  w: number;
  h: number;
  n_keys?: number;
  first_note?: number;
  y_index?: number;
  extra?: string;
}
/** A frame of the layout and monitor sections, with its decoded fields. */
interface ToolsFrame {
  desc: string;
  cmd: number;
  seq: number;
  payload: string;
  frame: string;
  fields?: {
    status?: number;
    offset?: number;
    max?: number;
    total?: number;
    data?: string;
    kinds?: number;
    interval_ms?: number;
    timeout_ms?: number;
    kind?: number;
    first?: number;
    row?: number;
    rows?: number;
    cols?: number;
    values?: number[];
  };
}
interface LayoutVectors {
  cap_layout: number;
  shapes: Record<string, number>;
  layout: { hex: string; version: number; width: number; height: number; items: VectorLayoutItem[] };
  /** The keys item's keys: index, black, x, y, w, h. */
  keys: [number, boolean, number, number, number, number][];
  frames: ToolsFrame[];
}
interface MonitorVectors {
  cap_monitor: number;
  kinds: Record<string, number>;
  raw_kinds: Record<string, number>;
  no_reading: number;
  frames: ToolsFrame[];
}
interface Vectors {
  config?: ConfigVectors;
  layout?: LayoutVectors;
  monitor?: MonitorVectors;
  /** Host feedback (§4.6): a list of frames, or an object holding one as `frames`. */
  feedback?: VectorFrame[] | { frames: VectorFrame[] };
  u14: IntVector[];
  u28: IntVector[];
  u32: IntVector[];
  pack7: { raw: string; packed: string }[];
  checksum: { body: string; chk: number }[];
  frames: { desc: string; cmd: number; seq: number; payload: string; frame: string }[];
  bad_frames: { desc: string; frame: string; error: string }[];
  chunk_plan: { size: number; max_chunk: number; chunks: [number, number][] }[];
  image: {
    gfw: string;
    fields: {
      magic: number;
      hdr_version: number;
      board_id: number;
      image_size: number;
      crc32: number;
      fw_version: number;
      proto_version: number;
    };
  };
}

/**
 * @param text - Space-separated hex, or "".
 * @returns The bytes.
 */
function bytesOf(text: string): number[] {
  return text.trim() === ''
    ? []
    : text
        .trim()
        .split(/\s+/)
        .map((h) => Number.parseInt(h, 16));
}

const vectors: Vectors = JSON.parse(readFileSync(VECTORS_URL, 'utf8'));

/** What the vectors call each bad-frame error, in this module's words. */
const PROBLEMS: Record<string, string> = { checksum: FrameProblem.BadChecksum, length: FrameProblem.BadLength };

describe('protocol/test-vectors.json', () => {
  it('u14, u28 and u32', () => {
    for (const { value, bytes } of vectors.u14) {
      expect(encodeU14(value)).toEqual(bytesOf(bytes));
      expect(decodeU14(bytesOf(bytes))).toBe(value);
    }
    for (const { value, bytes } of vectors.u28) {
      expect(encodeU28(value)).toEqual(bytesOf(bytes));
      expect(decodeU28(bytesOf(bytes))).toBe(value);
    }
    for (const { value, bytes } of vectors.u32) {
      expect(encodeU32(value)).toEqual(bytesOf(bytes));
      expect(decodeU32(bytesOf(bytes))).toBe(value);
    }
  });

  it('8→7 packing', () => {
    for (const { raw, packed } of vectors.pack7) {
      expect(pack(bytesOf(raw))).toEqual(bytesOf(packed));
      expect(unpack(bytesOf(packed))).toEqual(bytesOf(raw));
    }
  });

  it('checksums', () => {
    for (const { body, chk } of vectors.checksum) {
      expect(checksum(bytesOf(body))).toBe(chk);
    }
  });

  it('frames', () => {
    for (const { desc, cmd, seq, payload, frame } of vectors.frames) {
      expect(Array.from(encodeFrame(cmd, seq, bytesOf(payload))), desc).toEqual(bytesOf(frame));
      expect(decodeFrame(bytesOf(frame)), desc).toEqual({
        ok: true,
        frame: { version: 1, cmd, seq, payload: bytesOf(payload) },
      });
    }
    for (const { desc, frame, error } of vectors.bad_frames) {
      expect(decodeFrame(bytesOf(frame)), desc).toEqual({ ok: false, problem: PROBLEMS[error] });
    }
  });

  it('HELLO replies', () => {
    const replies = vectors.frames.filter(({ cmd }) => cmd === (Command.Hello | REPLY_FLAG));
    const nodes = replies.map(({ payload }) => parseHello(bytesOf(payload).slice(1)).nodeName);
    expect(nodes).toEqual([null, 'keystation-mini32']);
  });

  it('chunk plans', () => {
    for (const { size, max_chunk, chunks } of vectors.chunk_plan) {
      expect(planChunks(size, max_chunk).map((c) => [c.offset, c.length])).toEqual(chunks);
    }
  });

  it('the mkimage image', () => {
    const gfw = Uint8Array.from(bytesOf(vectors.image.gfw));
    const f = vectors.image.fields;
    expect(readHeader(gfw)).toEqual({
      magic: f.magic,
      hdrVersion: f.hdr_version,
      boardId: f.board_id,
      imageSize: f.image_size,
      crc32: f.crc32,
      fwVersion: f.fw_version,
      protoVersion: f.proto_version,
    });
    const result = validateImage(gfw, f.board_id);
    expect(result.ok ? [] : result.problems).toEqual([]);
  });
});

/**
 * A parsed param in the vectors' words: absent strings and lists empty, one default unless per index.
 *
 * @param param - From `parseSchema`.
 * @returns The vector form.
 */
function asVectorParam(param: ParamSpec): VectorParam {
  const isPerIndex = (param.flags & ParamFlag.PerIndexDefault) !== 0;
  return {
    id: param.id,
    type: param.rawType,
    group: param.group,
    count: param.count,
    flags: param.flags,
    min: param.min,
    max: param.max,
    defaults: isPerIndex ? param.defaults : param.defaults.slice(0, 1),
    name: param.name,
    label: param.label,
    unit: param.unit ?? '',
    index_labels: param.indexLabels ?? [],
    options: param.options ?? [],
  };
}

/** What the vectors call each bad-schema error, as a message this parser throws. */
const SCHEMA_PROBLEMS: Record<string, RegExp> = { truncated: /ends early/, version: /schema version/ };

describe.runIf(vectors.config !== undefined)('protocol/test-vectors.json config', () => {
  const config = vectors.config as ConfigVectors;

  it('s32', () => {
    for (const { value, bytes } of config.s32) {
      expect(encodeS32(value)).toEqual(bytesOf(bytes));
      expect(decodeS32(bytesOf(bytes))).toBe(value);
    }
  });

  it('the example schema', () => {
    const raw = bytesOf(config.schema.raw);
    expect(raw).toHaveLength(config.schema.size);
    const schema = parseSchema(raw);
    expect({ version: schema.version, groups: schema.groups, params: schema.params.map(asVectorParam) }).toEqual({
      ...config.schema.parsed,
      params: config.schema.parsed.params.map((p) => ({ options: [], ...p })),
    });
  });

  it('bad schemas', () => {
    for (const { desc, raw, error } of config.bad_schemas) {
      const parse = () => parseSchema(bytesOf(raw));
      expect(parse, desc).toThrow(SchemaError);
      expect(parse, desc).toThrow(SCHEMA_PROBLEMS[error] ?? /./);
    }
  });

  it('frames', () => {
    for (const { desc, cmd, seq, payload, frame, fields = {} } of config.frames) {
      const body = bytesOf(payload);
      expect(Array.from(encodeFrame(cmd, seq, body)), desc).toEqual(bytesOf(frame));
      const isReply = cmd >= REPLY_FLAG && cmd < Unsolicited.Log;
      const status = fields.status;
      if (isReply && status !== Status.Ok) {
        expect(body, desc).toEqual([status]);
        continue;
      }
      const rest = isReply ? body.slice(1) : body;
      const { id = 0, index = 0, n = 0, values = [] } = fields;
      switch (cmd) {
        case Command.GetSchema:
          expect(getSchemaPayload(fields.offset ?? 0, fields.max ?? 0), desc).toEqual(body);
          break;
        case Command.GetSchema | REPLY_FLAG:
          expect(parseSchemaWindow(rest), desc).toEqual({
            total: fields.total,
            offset: fields.offset,
            data: bytesOf(fields.data ?? ''),
          });
          break;
        case Command.GetParam:
          expect(getParamPayload(id, index), desc).toEqual(body);
          break;
        case Command.SetParam:
          expect(setParamPayload({ id, index, value: fields.value ?? 0 }), desc).toEqual(body);
          break;
        case Command.GetParam | REPLY_FLAG:
        case Command.SetParam | REPLY_FLAG:
          expect(parseParamValue(rest), desc).toEqual({ id, index, value: fields.value });
          break;
        case Command.GetParams:
          expect(getParamsPayload(id, index, n), desc).toEqual(body);
          break;
        case Command.GetParams | REPLY_FLAG:
          expect(parseParamRun(rest), desc).toEqual({ id, index, values });
          expect(values, desc).toHaveLength(n);
          break;
        case Command.SetParams:
          expect(setParamsPayload({ id, index, values }), desc).toEqual(body);
          break;
        case Command.SetParams | REPLY_FLAG:
          expect(parseParamRunEcho(rest), desc).toEqual({ id, index, n });
          break;
        case Command.Commit:
        case Command.FactoryReset:
          expect(body, desc).toEqual([]);
          break;
        case Command.Commit | REPLY_FLAG:
        case Command.FactoryReset | REPLY_FLAG:
          expect(rest, desc).toEqual([]);
          break;
        case Unsolicited.ParamChanged:
          expect(parseDeviceMessage({ version: 1, cmd, seq, payload: body }), desc).toEqual({
            kind: 'param',
            id,
            index,
            value: fields.value,
          });
          break;
        case Unsolicited.Event: {
          const message = parseDeviceMessage({ version: 1, cmd, seq, payload: body });
          expect(message, desc).toEqual({
            kind: 'event',
            type: fields.type,
            index,
            value: fields.value,
            tMs: fields.t_ms,
          });
          if (fields.delta !== undefined) {
            expect(encoderDelta(fields.value ?? 0), desc).toBe(fields.delta);
          }
          break;
        }
        default:
          throw new Error(`no check for ${desc} (cmd ${cmd})`);
      }
    }
  });
});

describe.runIf(vectors.feedback !== undefined)('protocol/test-vectors.json feedback', () => {
  const section = vectors.feedback;
  const frames = Array.isArray(section) ? section : (section?.frames ?? []);

  it('frames', () => {
    for (const { desc, cmd, seq, payload, frame, fields } of frames) {
      const body = bytesOf(payload);
      expect(Array.from(encodeFrame(cmd, seq, body)), desc).toEqual(bytesOf(frame));
      expect(decodeFrame(bytesOf(frame)), desc).toEqual({ ok: true, frame: { version: 1, cmd, seq, payload: body } });
      const isOkComponentReply = cmd === (Command.GetComponent | REPLY_FLAG) && body[0] === Status.Ok;
      if (isOkComponentReply) {
        const component = parseComponent(body.slice(1));
        // The added fields (§4.6.1): null when older firmware leaves them out.
        if (component.kind === 3) {
          expect(component.takeover, desc).toBe(fields?.takeover);
        } else if (component.kind === 4) {
          expect(component.mode, desc).toBe(fields?.mode);
        } else if (component.kind === 5) {
          expect(component.owner, desc).toBe(fields?.owner);
        }
      }
      if (cmd === Unsolicited.Booted) {
        const message = parseDeviceMessage({ version: 1, cmd, seq, payload: body });
        expect(message?.kind, desc).toBe('booted');
        const hello = message?.kind === 'booted' ? message.hello : null;
        expect(hello?.boardId, desc).toBe(fields?.board_id);
        expect(hello?.fwVersion, desc).toBe(fields?.fw_version);
        expect(hello?.caps, desc).toBe(fields?.caps);
        expect(hello?.nodeName, desc).toBe(fields?.node);
        expect(hello?.uid, desc).toEqual(Array.from(fields?.uid?.match(/../g) ?? [], (h) => Number.parseInt(h, 16)));
      }
      const isNotification = cmd >= NOTIFICATION_FIRST && cmd <= NOTIFICATION_LAST;
      const isKnown =
        isNotification ||
        cmd === Command.GetComponent ||
        cmd === (Command.GetComponent | REPLY_FLAG) ||
        cmd === Unsolicited.Booted;
      expect(isKnown, desc).toBe(true);
    }
  });
});

/** Places the key geometry is rounded to in the vectors. */
const KEY_PLACES = 4;

describe('protocol/test-vectors.json: layout and raw readings (§4.7, §4.8)', () => {
  const { layout, monitor } = vectors;

  it.runIf(layout !== undefined)('parses the layout blob and draws its keys by the rule', () => {
    if (layout === undefined) {
      return;
    }
    expect(Capability.Layout).toBe(layout.cap_layout);
    expect(LayoutShape).toEqual({
      Button: layout.shapes.button,
      RoundButton: layout.shapes.round_button,
      Knob: layout.shapes.knob,
      Encoder: layout.shapes.encoder,
      Fader: layout.shapes.fader,
      Wheel: layout.shapes.wheel,
      Pad: layout.shapes.pad,
      Display: layout.shapes.display,
      Keys: layout.shapes.keys,
      Xy: layout.shapes.xy,
    });
    const parsed = parseLayout(bytesOf(layout.layout.hex));
    expect(parsed.width).toBe(layout.layout.width);
    expect(parsed.height).toBe(layout.layout.height);
    expect(parsed.items).toEqual(
      layout.layout.items.map((item) => ({
        kind: item.kind,
        index: item.index,
        shape: item.shape,
        x: item.x,
        y: item.y,
        w: item.w,
        h: item.h,
        ...(item.n_keys === undefined ? {} : { keys: { count: item.n_keys, firstNote: item.first_note } }),
        ...(item.y_index === undefined ? {} : { yIndex: item.y_index }),
      })),
    );
    const keysItem = parsed.items.find((item) => item.shape === LayoutShape.Keys);
    expect(keysItem).toBeDefined();
    if (keysItem === undefined) {
      return;
    }
    const round = (v: number) => Number(v.toFixed(KEY_PLACES));
    const drawn = keyRects(keysItem)
      .sort((a, b) => a.key - b.key)
      .map((key) => [key.key, key.isBlack, round(key.x), round(key.y), round(key.w), round(key.h)]);
    expect(drawn).toEqual(layout.keys);
  });

  it.runIf(layout !== undefined)('GET_LAYOUT frames', () => {
    for (const { desc, cmd, seq, payload, frame, fields } of layout?.frames ?? []) {
      expect(toHexList(encodeFrame(cmd, seq, bytesOf(payload))), desc).toEqual(bytesOf(frame));
      if (cmd === Command.GetLayout) {
        expect(getSchemaPayload(fields?.offset ?? 0, fields?.max ?? 0), desc).toEqual(bytesOf(payload));
        continue;
      }
      expect(cmd, desc).toBe(Command.GetLayout | REPLY_FLAG);
      const [status, ...body] = bytesOf(payload);
      expect(status, desc).toBe(fields?.status);
      if (status === Status.Ok) {
        const window = parseSchemaWindow(body);
        expect(window.total, desc).toBe(fields?.total);
        expect(window.offset, desc).toBe(fields?.offset);
        expect(window.data, desc).toEqual(bytesOf(fields?.data ?? ''));
      }
    }
  });

  it.runIf(monitor !== undefined)('MONITOR and RAW frames', () => {
    if (monitor === undefined) {
      return;
    }
    expect(Capability.Monitor).toBe(monitor.cap_monitor);
    expect(MonitorKind).toEqual({
      Buttons: monitor.kinds.buttons,
      KeyMatrix: monitor.kinds.key_matrix,
      Analog: monitor.kinds.analog,
      Encoders: monitor.kinds.encoders,
      Pads: monitor.kinds.pads,
    });
    expect(RawKind).toEqual({
      Buttons: monitor.raw_kinds.buttons,
      KeyMatrix: monitor.raw_kinds.key_matrix,
      Analog: monitor.raw_kinds.analog,
      Encoders: monitor.raw_kinds.encoders,
      Pads: monitor.raw_kinds.pads,
    });
    expect(RAW_NO_READING).toBe(monitor.no_reading);
    for (const { desc, cmd, seq, payload, frame, fields } of monitor.frames) {
      expect(toHexList(encodeFrame(cmd, seq, bytesOf(payload))), desc).toEqual(bytesOf(frame));
      if (cmd === Command.Monitor) {
        expect(monitorPayload(fields?.kinds ?? 0), desc).toEqual(bytesOf(payload));
      } else if (cmd === (Command.Monitor | REPLY_FLAG)) {
        const [status, ...body] = bytesOf(payload);
        expect(status, desc).toBe(fields?.status);
        expect(parseMonitorReply(body), desc).toEqual({
          kinds: fields?.kinds,
          intervalMs: fields?.interval_ms,
          timeoutMs: fields?.timeout_ms,
        });
      } else {
        expect(cmd, desc).toBe(Unsolicited.Raw);
        const reading = parseRaw(bytesOf(payload));
        const values = fields?.values ?? [];
        switch (reading.kind) {
          case 'buttons':
            expect(fields?.kind, desc).toBe(RawKind.Buttons);
            expect(reading.first, desc).toBe(fields?.first);
            expect(reading.pressed.map(Number), desc).toEqual(values);
            break;
          case 'matrix':
            expect(fields?.kind, desc).toBe(RawKind.KeyMatrix);
            expect([reading.row, reading.rows, reading.cols], desc).toEqual([fields?.row, fields?.rows, fields?.cols]);
            expect(reading.closed.map(Number), desc).toEqual(values);
            break;
          case 'analog':
            expect(fields?.kind, desc).toBe(RawKind.Analog);
            expect(reading.first, desc).toBe(fields?.first);
            expect(
              reading.values.map((v) => v ?? RAW_NO_READING),
              desc,
            ).toEqual(values);
            break;
          case 'encoders':
            expect(fields?.kind, desc).toBe(RawKind.Encoders);
            expect(reading.first, desc).toBe(fields?.first);
            expect(reading.counts, desc).toEqual(values);
            break;
          case 'pads':
            expect(fields?.kind, desc).toBe(RawKind.Pads);
            expect(reading.first, desc).toBe(fields?.first);
            expect(reading.values, desc).toEqual(values);
            break;
          default:
            throw new Error(`${desc}: RAW kind ${fields?.kind} not parsed`);
        }
        const message = parseDeviceMessage({ version: 1, cmd, seq, payload: bytesOf(payload) });
        expect(message?.kind, desc).toBe('raw');
      }
    }
  });
});

/**
 * @param bytes - A frame.
 * @returns Its bytes as a plain list.
 */
function toHexList(bytes: Uint8Array): number[] {
  return Array.from(bytes);
}
